[Form]
public class AVAQuotationStatusModify extends FormRun
{
    AVAQuotationStatusModify    quotationStatusModify;
    SalesQuotationTable         salesQuotationTable;
    [FormObservable]
    DirPartyName                CompName;


}

public void init()
{
    super();

    if (!element.args() || !element.args().caller())
    {
        throw error(strfmt("@SYS22862",element.name()));
    }

    if (! ( classidget(element.args().caller()) == classidget(QuotationStatusModify)))
    {
        throw error(strfmt("@SYS22456",element.name(),classId2Name(classidget(QuotationStatusModify))));
    }


    QuotationStatusModify = element.args().caller();

    KCS_StatusId.text(QuotationStatusModify.parmStatusId());

    KCS_DecisionDate.dateValue(QuotationStatusModify.parmDecisionDate());
    KCS_AltStatusId.text(QuotationStatusModify.parmAltStatusId());
    KCS_ReasonId.text(QuotationStatusModify.parmReasonId());
    KCS_CompetitorId.text(QuotationStatusModify.parmCompId());
    CompName    = smmQuotationCompetitorGroup::find(str2Int64(QuotationStatusModify.parmCompId())).dirPartyName();

    KCS_StatusId.allowEdit(true);
    if(!QuotationStatusModify.parmSetDecisionDate())
    {
        KCS_DecisionDate.allowEdit(false);
    }
    KCS_AltStatusId.allowEdit(false);
    KCS_ReasonId.allowEdit(false);
    if(QuotationStatusModify.parmCompId() != '')
    {
        KCS_CompetitorId.allowEdit(false);
    }
    else
    {
        KCS_CompetitorId.allowEdit(true);
    }
}

edit KCS_StatusId editStatusId(boolean set, KCS_StatusId _statusId)
{
    if (set)
    {
        QuotationStatusModify.parmStatusId(_statusId);
    }
    return QuotationStatusModify.parmStatusId();
}

edit smmQuotationReasonId editReasonId(boolean set, smmQuotationReasonId _reasonId)
{
    if (set)
    {
        QuotationStatusModify.parmReasonId(_reasonId);
    }
    return QuotationStatusModify.parmReasonId();
}

edit KCS_StatusId editAltStatusId(boolean set, KCS_StatusId _altStatusId)
{
    if (set)
    {
        QuotationStatusModify.parmAltStatusId(_altStatusId);
    }
    return QuotationStatusModify.parmAltStatusId();
}

public boolean modified()
{
    KCS_QuotationStatus     tblKCS_QuotationStatus;
    boolean ret;
    TransDate d;

    ret = super();
    select firstonly tblKCS_QuotationStatus
    where tblKCS_QuotationStatus.KCS_StatusId == QuotationStatusModify.parmStatusId();

    // Folgekennzeichen (AltStatusId)
    QuotationStatusModify.parmAltStatusId(tblKCS_QuotationStatus.KCS_AltStatusId);
    KCS_AltStatusId.text(QuotationStatusModify.parmAltStatusId());

    // Angebotsstatus (QuotationStatus)
    QuotationStatusModify.parmQuotationStatus(tblKCS_QuotationStatus.KCS_SalesQuotationStatus);

    // Mitbewerberkennung (CompetitorId)
    if(tblKCS_QuotationStatus.KCS_CompetitorId != '')
    {
        QuotationStatusModify.parmComp(tblKCS_QuotationStatus.KCS_Competitor);
        QuotationStatusModify.parmCompId(tblKCS_QuotationStatus.KCS_CompetitorId);
        KCS_CompetitorId.text(QuotationStatusModify.parmCompId());
        CompName    = smmQuotationCompetitorGroup::find(str2Int64(QuotationStatusModify.parmCompId())).dirPartyName();
        KCS_CompetitorId.allowEdit(false);
    }
    else
    {
        QuotationStatusModify.parmComp();
        QuotationStatusModify.parmCompId();
        KCS_CompetitorId.text('');
        KCS_Competitor.text('');
        KCS_CompetitorId.allowEdit(true);
    }

    // Entscheidungsdatum (DecisionDate)
    QuotationStatusModify.parmSetDecisionDate(tblKCS_QuotationStatus.KCS_SetDecisionDate);
    if(tblKCS_QuotationStatus.KCS_SetDecisionDate == NoYes::Yes)
    {
        if(QuotationStatusModify.parmDecisionDate() == datenull())
        {
            d = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            KCS_DecisionDate.dateValue(d);
        }
        else
        {
            KCS_DecisionDate.dateValue(QuotationStatusModify.parmDecisionDate());
        }
        KCS_DecisionDate.allowEdit(true);
    }
    else
    {
        KCS_DecisionDate.dateValue();
        KCS_DecisionDate.allowEdit(false);
    }

    // Grund (ReasonId)
    QuotationStatusModify.parmReasonId(tblKCS_QuotationStatus.KCS_ReasonId);
    KCS_ReasonId.text(QuotationStatusModify.parmReasonId());

    return ret;
}

public void lookup()
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    SysTableLookup sysTableLookup =
    SysTableLookup::newParameters(tableNum(KCS_QuotationStatus), this);
    sysTableLookup.addLookupField(fieldNum(KCS_QuotationStatus, KCS_StatusId));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_SetDecisionDate));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_Competitor));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_CompetitorId));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_ReasonId));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_SalesQuotationStatus));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_StatusDescription));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus, KCS_AltStatusId));
    sysTableLookup.addLookupfield(fieldNum(KCS_QuotationStatus,KCS_Color));
    queryBuildDataSource = query.addDataSource(tableNum(KCS_QuotationStatus));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;

    ret = super();

    //element.redraw();
    CompName    = smmQuotationCompetitorGroup::find(str2Int64(this.valueStr())).dirPartyName();

    return ret;
}

public void lookup()
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    SysTableLookup sysTableLookup =
    SysTableLookup::newParameters(tableNum(smmQuotationCompetitorGroup), this);
    sysTableLookup.addLookupField(fieldNum(smmQuotationCompetitorGroup, Party));
    sysTableLookup.addLookupMethod(tableMethodStr(smmQuotationCompetitorGroup,dirPartyName));
    queryBuildDataSource = query.addDataSource(tableNum(smmQuotationCompetitorGroup));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
